import { StyleFn } from "..";

const DISPLAY_VALUES = ["none", "block", "inline", "flex", "table"];

// TODO refactor with Container element
const UP = (value: number) => `@media (min-width:${value}px)`;

export const d: StyleFn = (theme, mode) => {
  const { breakpoint } = theme.responsive;

  return {
    _none: { display: "none" },
    // media query classes : 'ds-d-{breakpoint}--{value}'
    ...Object.keys(breakpoint).reduce(
      (mediaQueryClasses: Object, bp: string) => ({
        ...mediaQueryClasses,
        [UP((breakpoint as any)[bp])]: DISPLAY_VALUES.reduce(
          (classes: Object, display: string) => ({
            ...classes,
            [`${bp}--${display}`]: { display },
          }),
          {}
        ),
      }),
      {}
    ),
  };
};
